    #[test]
    fn test_squashed_pipeline_unlink_touch_and_container_multi_reads() {
        let mut rt = monoio::RuntimeBuilder::<monoio::FusionDriver>::new()
            .enable_all()
            .build()
            .unwrap();

        rt.block_on(async {
            let (senders_mesh, _receivers) = crate::mailbox::create_shard_mesh(1);
            let db = Rc::new(RefCell::new(ShardDb::new(9995)));
            let router = Router::new(
                0,
                1,
                9995,
                db,
                senders_mesh[0].clone(),
                None,
                Rc::new(RefCell::new(crate::pubsub::PubSubHub::new())),
                std::env::temp_dir(),
            );
            let client_registry = RefCell::new(hashbrown::HashMap::new());
            let mut asking = false;
            let mut authenticated = true;
            let mut auth_user = String::from("default");
            let mut out = Vec::new();
            let responders = vec![std::sync::Arc::new(crate::mailbox::BatchResponder::new())];
            let mut remote_batches = vec![Vec::new()];
            let mut items_pool = vec![Vec::new()];
            let mut results_pool = vec![Vec::new()];
            let mut squashed_responses = Vec::new();

            let mut cmds = vec![
                Command::Hset {
                    key: Bytes::from("h1"),
                    fields: smallvec::smallvec![
                        (Bytes::from("f1"), Bytes::from("v1")),
                        (Bytes::from("f2"), Bytes::from("v2")),
                    ],
                },
                Command::Hmget {
                    key: Bytes::from("h1"),
                    fields: vec![Bytes::from("f1"), Bytes::from("missing"), Bytes::from("f2")],
                },
                Command::Sadd {
                    key: Bytes::from("s1"),
                    members: smallvec::smallvec![Bytes::from("m1"), Bytes::from("m2")],
                },
                Command::Smismember {
                    key: Bytes::from("s1"),
                    members: vec![Bytes::from("m1"), Bytes::from("m_none"), Bytes::from("m2")],
                },
                Command::Zadd {
                    key: Bytes::from("z1"),
                    elements: smallvec::smallvec![
                        (1.5, Bytes::from("zm1")),
                        (2.5, Bytes::from("zm2")),
                    ],
                    flags: crate::table::ZAddFlags::default(),
                },
                Command::Zmscore {
                    key: Bytes::from("z1"),
                    members: vec![
                        Bytes::from("zm1"),
                        Bytes::from("zm_none"),
                        Bytes::from("zm2"),
                    ],
                },
                Command::Touch(smallvec::smallvec![
                    Bytes::from("h1"),
                    Bytes::from("s1"),
                    Bytes::from("z1"),
                    Bytes::from("no_such_key"),
                ]),
                Command::Unlink(smallvec::smallvec![
                    Bytes::from("h1"),
                    Bytes::from("s1"),
                    Bytes::from("no_such_key"),
                ]),
                Command::Touch(smallvec::smallvec![
                    Bytes::from("h1"),
                    Bytes::from("s1"),
                    Bytes::from("z1"),
                ]),
            ];

            let quit = execute_commands_squashed(
                &mut cmds,
                false,
                &router,
                &responders,
                &mut remote_batches,
                &mut items_pool,
                &mut results_pool,
                &mut squashed_responses,
                1,
                &client_registry,
                &mut out,
                &mut asking,
                &mut authenticated,
                &mut auth_user,
            )
            .await;
            assert!(!quit);
            let expected = concat!(
                ":2\r\n",
                "*3\r\n$2\r\nv1\r\n$-1\r\n$2\r\nv2\r\n",
                ":2\r\n",
                "*3\r\n:1\r\n:0\r\n:1\r\n",
                ":2\r\n",
                "*3\r\n$3\r\n1.5\r\n$-1\r\n$3\r\n2.5\r\n",
                ":3\r\n",
                ":2\r\n",
                ":1\r\n",
            );
            assert_eq!(out, expected.as_bytes());
        });
    }

    #[test]
    fn test_squashed_pipeline_hdel_srem_zrem_fast_paths() {
        let mut rt = monoio::RuntimeBuilder::<monoio::FusionDriver>::new()
            .enable_all()
            .build()
            .unwrap();

        rt.block_on(async {
            let (senders_mesh, _receivers) = crate::mailbox::create_shard_mesh(1);
            let db = Rc::new(RefCell::new(ShardDb::new(9993)));
            let router = Router::new(
                0,
                1,
                9993,
                db,
                senders_mesh[0].clone(),
                None,
                Rc::new(RefCell::new(crate::pubsub::PubSubHub::new())),
                std::env::temp_dir(),
            );
            let client_registry = RefCell::new(hashbrown::HashMap::new());
            let mut asking = false;
            let mut authenticated = true;
            let mut auth_user = String::from("default");
            let mut out = Vec::new();
            let responders = vec![std::sync::Arc::new(crate::mailbox::BatchResponder::new())];
            let mut remote_batches = vec![Vec::new()];
            let mut items_pool = vec![Vec::new()];
            let mut results_pool = vec![Vec::new()];
            let mut squashed_responses = Vec::new();
            let b = |s: &'static str| Bytes::from_static(s.as_bytes());

            let mut cmds = vec![
                Command::Hset {
                    key: b("h"),
                    fields: smallvec::smallvec![
                        (b("a"), b("1")),
                        (b("b"), b("2")),
                        (b("c"), b("3"))
                    ],
                },
                Command::Hdel {
                    key: b("h"),
                    fields: smallvec::smallvec![b("a")],
                },
                Command::Hdel {
                    key: b("h"),
                    fields: smallvec::smallvec![b("b"), b("c"), b("x")],
                },
                Command::Hdel {
                    key: b("h"),
                    fields: smallvec::smallvec![b("a")],
                },
                Command::Sadd {
                    key: b("s"),
                    members: smallvec::smallvec![b("a"), b("b")],
                },
                Command::Srem {
                    key: b("s"),
                    members: smallvec::smallvec![b("a"), b("x")],
                },
                Command::Srem {
                    key: b("s"),
                    members: smallvec::smallvec![b("b")],
                },
                Command::Zadd {
                    key: b("z"),
                    elements: smallvec::smallvec![(1.0, b("a")), (2.0, b("b"))],
                    flags: crate::table::ZAddFlags::default(),
                },
                Command::Zrem {
                    key: b("z"),
                    members: smallvec::smallvec![b("a"), b("b"), b("x")],
                },
                // Removing the last item deletes the key.
                Command::Exists(smallvec::smallvec![b("h"), b("s"), b("z")]),
                Command::Set {
                    key: b("str"),
                    value: b("v"),
                    expire_in: None,
                    condition: crate::resp::SetCondition::None,
                    get: false,
                    keepttl: false,
                    past_expired: false,
                },
                Command::Hdel {
                    key: b("str"),
                    fields: smallvec::smallvec![b("a")],
                },
                Command::Srem {
                    key: b("str"),
                    members: smallvec::smallvec![b("a")],
                },
                Command::Zrem {
                    key: b("str"),
                    members: smallvec::smallvec![b("a")],
                },
            ];

            let quit = execute_commands_squashed(
                &mut cmds,
                false,
                &router,
                &responders,
                &mut remote_batches,
                &mut items_pool,
                &mut results_pool,
                &mut squashed_responses,
                1,
                &client_registry,
                &mut out,
                &mut asking,
                &mut authenticated,
                &mut auth_user,
            )
            .await;
            assert!(!quit);
            let wt = "-WRONGTYPE Operation against a key holding the wrong kind of value\r\n";
            let expected = format!(
                ":3\r\n:1\r\n:2\r\n:0\r\n:2\r\n:1\r\n:1\r\n:2\r\n:2\r\n:0\r\n+OK\r\n{wt}{wt}{wt}"
            );
            assert_eq!(String::from_utf8_lossy(&out), expected);
        });
    }

    #[test]
    fn test_squashed_pipeline_rpush_spop_zpopmin_fast_paths() {
        let mut rt = monoio::RuntimeBuilder::<monoio::FusionDriver>::new()
            .enable_all()
            .build()
            .unwrap();

        rt.block_on(async {
            let (senders_mesh, _receivers) = crate::mailbox::create_shard_mesh(1);
            let db = Rc::new(RefCell::new(ShardDb::new(9994)));
            let router = Router::new(
                0,
                1,
                9994,
                db,
                senders_mesh[0].clone(),
                None,
                Rc::new(RefCell::new(crate::pubsub::PubSubHub::new())),
                std::env::temp_dir(),
            );
            let client_registry = RefCell::new(hashbrown::HashMap::new());
            let mut asking = false;
            let mut authenticated = true;
            let mut auth_user = String::from("default");
            let mut out = Vec::new();
            let responders = vec![std::sync::Arc::new(crate::mailbox::BatchResponder::new())];
            let mut remote_batches = vec![Vec::new()];
            let mut items_pool = vec![Vec::new()];
            let mut results_pool = vec![Vec::new()];
            let mut squashed_responses = Vec::new();

            let mut cmds = vec![
                Command::Rpush {
                    key: Bytes::from("l"),
                    values: smallvec::smallvec![Bytes::from("a"), Bytes::from("b")],
                },
                Command::Rpush {
                    key: Bytes::from("l"),
                    values: smallvec::smallvec![Bytes::from("c")],
                },
                Command::Lrange {
                    key: Bytes::from("l"),
                    start: 0,
                    stop: -1,
                },
                Command::Sadd {
                    key: Bytes::from("s"),
                    members: smallvec::smallvec![Bytes::from("m1")],
                },
                Command::Spop {
                    key: Bytes::from("s"),
                    count: None,
                },
                Command::Spop {
                    key: Bytes::from("s"),
                    count: None,
                },
                Command::Zadd {
                    key: Bytes::from("z"),
                    elements: smallvec::smallvec![
                        (2.5, Bytes::from("zb")),
                        (1.5, Bytes::from("za")),
                    ],
                    flags: crate::table::ZAddFlags::default(),
                },
                Command::Zpopmin {
                    key: Bytes::from("z"),
                    count: None,
                },
                Command::Zpopmin {
                    key: Bytes::from("z"),
                    count: None,
                },
                Command::Zpopmin {
                    key: Bytes::from("z"),
                    count: None,
                },
                // Popping the last member deletes the key.
                Command::Exists(smallvec::smallvec![Bytes::from("s"), Bytes::from("z")]),
                Command::Spop {
                    key: Bytes::from("l"),
                    count: None,
                },
                Command::Zpopmin {
                    key: Bytes::from("l"),
                    count: None,
                },
            ];

            let quit = execute_commands_squashed(
                &mut cmds,
                false,
                &router,
                &responders,
                &mut remote_batches,
                &mut items_pool,
                &mut results_pool,
                &mut squashed_responses,
                1,
                &client_registry,
                &mut out,
                &mut asking,
                &mut authenticated,
                &mut auth_user,
            )
            .await;
            assert!(!quit);
            let expected = concat!(
                ":2\r\n",
                ":3\r\n",
                "*3\r\n$1\r\na\r\n$1\r\nb\r\n$1\r\nc\r\n",
                ":1\r\n",
                "$2\r\nm1\r\n",
                "$-1\r\n",
                ":2\r\n",
                "*2\r\n$2\r\nza\r\n$3\r\n1.5\r\n",
                "*2\r\n$2\r\nzb\r\n$3\r\n2.5\r\n",
                "*0\r\n",
                ":0\r\n",
                "-WRONGTYPE Operation against a key holding the wrong kind of value\r\n",
                "-WRONGTYPE Operation against a key holding the wrong kind of value\r\n",
            );
            assert_eq!(String::from_utf8_lossy(&out), expected);
        });
    }
